from pathlib import Path

runtime = Path('google_health_viewer/agent_runtime_v2.py')
text = runtime.read_text(encoding='utf-8')

text = text.replace(
    'MAX_FACTORY_REPAIR_ATTEMPTS = 3\nMAX_RAW_SERIES_PROBES_BEFORE_FACTORY = 2\n',
    'MAX_FACTORY_REPAIR_ATTEMPTS = 3\nMAX_FACTORY_GATE_REFUSALS = 2\nMAX_RAW_SERIES_PROBES_BEFORE_FACTORY = 2\n',
)

text = text.replace(
    '- Prefer semantic deterministic tools (for example calculate_cardio_load) over guessing raw metric names.\n',
    '- Prefer semantic deterministic tools (for example calculate_cardio_load) over guessing raw metric names.\n'
    '- Tool names are NEVER metric identifiers: do not pass calculate_cardio_load, get_sleep_stage_series, or any other function name to get_metric_series/get_data_coverage/get_baseline.\n'
    '- When the runtime Tool Factory gate exposes only create_learned_tool, you must call it; do not answer directly before resolving or exhausting that gate.\n',
)

old = '''        schemas = self.tools.tool_schemas()\n        physical_limit = (\n'''
new = '''        schemas = self.tools.tool_schemas()\n        tool_function_names = {\n            str(item.get("function", {}).get("name") or "")\n            for item in schemas\n            if isinstance(item, dict) and isinstance(item.get("function"), dict)\n        }\n        metric_reader_tools = {\n            "get_metric_series",\n            "get_data_coverage",\n            "get_daily_summary",\n            "get_baseline",\n            "get_missing_data",\n            "detect_outliers",\n            "detect_trends",\n        }\n        physical_limit = (\n'''
if 'tool_function_names = {' not in text:
    text = text.replace(old, new)

old = '''        factory_gate_required = False\n        factory_resolution_seen = False\n        raw_series_probes = 0\n'''
new = '''        factory_gate_required = False\n        factory_resolution_seen = False\n        factory_gate_refusals = 0\n        raw_series_probes = 0\n'''
text = text.replace(old, new)

old = '''            if not tool_calls:\n                final_answer = str(message.get("content") or "").strip()\n                if final_answer:\n                    if answer_callback:\n                        answer_callback(final_answer)\n                    event(_("Agent finished the analysis."))\n                    return final_answer\n                raise LocalAIError(_("The local model returned neither an answer nor a tool call."))\n'''
new = '''            if not tool_calls:\n                final_answer = str(message.get("content") or "").strip()\n                if factory_gate_required and not factory_disabled:\n                    factory_gate_refusals += 1\n                    if final_answer:\n                        messages.append({"role": "assistant", "content": final_answer})\n                    messages.append(\n                        {\n                            "role": "system",\n                            "content": (\n                                "RUNTIME TOOL FACTORY GATE: the direct answer was rejected because the "\n                                "reusable capability gap has not been resolved. Call create_learned_tool "\n                                "now. Tool names such as calculate_cardio_load and get_sleep_stage_series "\n                                "are functions, not metric identifiers, so generic metric readers cannot "\n                                "establish that those capabilities have no data. Build the learned pipeline "\n                                "with call_tool/extract_series/baseline/filter_relative/event_response as "\n                                "needed. Do not claim data are absent until the semantic built-in itself has "\n                                "been executed (directly or by the learned tool)."\n                            ),\n                        }\n                    )\n                    event(\n                        _(\n                            "Direct answer blocked by Tool Factory gate · the reusable capability must be resolved first."\n                        )\n                    )\n                    if factory_gate_refusals <= MAX_FACTORY_GATE_REFUSALS:\n                        continue\n                    factory_gate_required = False\n                    factory_disabled = True\n                    event(_("Tool Factory gate attempt limit reached · finalising without inventing missing data."))\n                    return self._final_answer(\n                        model=model,\n                        messages=messages,\n                        max_tokens=max_tokens,\n                        physical_limit=physical_limit,\n                        think=think,\n                        cancel_callback=cancel_callback,\n                        event=event,\n                        answer_callback=answer_callback,\n                    )\n                if final_answer:\n                    if answer_callback:\n                        answer_callback(final_answer)\n                    event(_("Agent finished the analysis."))\n                    return final_answer\n                raise LocalAIError(_("The local model returned neither an answer nor a tool call."))\n'''
if 'Direct answer blocked by Tool Factory gate' not in text:
    text = text.replace(old, new)

old = '''                blocked_for_factory = False\n                if name == "get_metric_series" and factory_candidate and not factory_resolution_seen:\n'''
new = '''                blocked_for_factory = False\n                metric_argument = str(args.get("metric") or "").strip()\n                if (\n                    name in metric_reader_tools\n                    and metric_argument\n                    and metric_argument in tool_function_names\n                ):\n                    blocked_for_factory = True\n                    factory_gate_required = factory_candidate and not factory_resolution_seen\n                    result = {\n                        "status": "invalid_metric_identifier",\n                        "error": (\n                            f"'{metric_argument}' is a tool/function name, not a raw VitalChronicle "\n                            "metric identifier. Call that semantic tool directly, or compose it inside "\n                            "a learned tool using call_tool. This result does NOT mean the underlying "\n                            "health data are missing."\n                        ),\n                        "tool_name": metric_argument,\n                    }\n                    event(\n                        _(\n                            "Tool name rejected as a raw metric identifier: {metric}",\n                            metric=metric_argument,\n                        )\n                    )\n                if (\n                    not blocked_for_factory\n                    and name == "get_metric_series"\n                    and factory_candidate\n                    and not factory_resolution_seen\n                ):\n'''
if 'Tool name rejected as a raw metric identifier' not in text:
    text = text.replace(old, new)

runtime.write_text(text, encoding='utf-8')

tests = Path('tests/test_agent_tool_factory_v2.py')
t = tests.read_text(encoding='utf-8')
if 'class GateRefusalRuntime' not in t:
    t += '''\n\nclass GateRefusalRuntime(AgentRuntime):\n    def __init__(self, health_store, agent_store):\n        super().__init__(health_store, agent_store)\n        self.turn = 0\n        self.available_by_turn: list[set[str]] = []\n\n    def _chat_once(self, **kwargs):\n        self.turn += 1\n        names = {\n            str(item.get("function", {}).get("name") or "")\n            for item in kwargs.get("tools", [])\n            if isinstance(item, dict)\n        }\n        self.available_by_turn.append(names)\n        if self.turn <= 4:\n            return {\n                "content": "",\n                "tool_calls": [\n                    {"function": {"name": "get_available_metrics", "arguments": {}}}\n                ],\n            }\n        if self.turn == 5:\n            return {"content": "Non ci sono dati, quindi rispondo subito."}\n        if self.turn == 6:\n            return {\n                "content": "",\n                "tool_calls": [\n                    {\n                        "function": {\n                            "name": "create_learned_tool",\n                            "arguments": {\n                                "name": "gate_resolved_tool",\n                                "description": "Reusable composed temporal analysis",\n                                "capability": "analysis.composed.personal_baseline.temporal_event_response",\n                                "pipeline": [{"op": "return"}],\n                            },\n                        }\n                    }\n                ],\n            }\n        return {"content": "Risposta finale dopo la creazione del tool."}\n\n\ndef test_factory_gate_rejects_direct_answer_until_capability_is_resolved(tmp_path):\n    store = AgentStore(tmp_path / "agent.sqlite3")\n    runtime = GateRefusalRuntime(DummyHealthStore(tmp_path / "health.sqlite3"), store)\n    events: list[str] = []\n    answer = runtime.analyze(\n        model="test",\n        snapshot={},\n        question=(\n            "Quando il carico supera del 20% la baseline personale, il sonno profondo della notte "\n            "successiva diminuisce e dopo quanti giorni torna al livello abituale?"\n        ),\n        history=[],\n        max_tokens=1024,\n        model_context_limit=None,\n        performance_profile="standard",\n        thread_id="gate-refusal-thread",\n        event_callback=events.append,\n    )\n    assert answer.startswith("Risposta finale dopo")\n    assert runtime.turn == 7\n    assert runtime.available_by_turn[4] == {"create_learned_tool"}\n    assert runtime.available_by_turn[5] == {"create_learned_tool"}\n    assert any("direct answer blocked" in event.lower() for event in events)\n\n\nclass ToolNameAsMetricRuntime(AgentRuntime):\n    def __init__(self, health_store, agent_store):\n        super().__init__(health_store, agent_store)\n        self.turn = 0\n\n    def _chat_once(self, **kwargs):\n        self.turn += 1\n        if self.turn == 1:\n            return {\n                "content": "",\n                "tool_calls": [\n                    {\n                        "function": {\n                            "name": "get_data_coverage",\n                            "arguments": {"metric": "calculate_cardio_load"},\n                        }\n                    }\n                ],\n            }\n        if self.turn == 2:\n            return {\n                "content": "",\n                "tool_calls": [\n                    {\n                        "function": {\n                            "name": "create_learned_tool",\n                            "arguments": {\n                                "name": "semantic_metric_router",\n                                "description": "Use semantic built-ins instead of tool names as metrics",\n                                "capability": "analysis.composed.personal_baseline.temporal_event_response",\n                                "pipeline": [{"op": "return"}],\n                            },\n                        }\n                    }\n                ],\n            }\n        return {"content": "Risposta finale corretta."}\n\n\ndef test_tool_name_cannot_be_misused_as_raw_metric_identifier(tmp_path):\n    store = AgentStore(tmp_path / "agent.sqlite3")\n    runtime = ToolNameAsMetricRuntime(DummyHealthStore(tmp_path / "health.sqlite3"), store)\n    events: list[str] = []\n    answer = runtime.analyze(\n        model="test",\n        snapshot={},\n        question=(\n            "Quando il carico supera del 20% la baseline personale, il sonno profondo della notte "\n            "successiva diminuisce e dopo quanti giorni torna al livello abituale?"\n        ),\n        history=[],\n        max_tokens=1024,\n        model_context_limit=None,\n        performance_profile="standard",\n        thread_id="tool-name-thread",\n        event_callback=events.append,\n    )\n    assert answer == "Risposta finale corretta."\n    assert any("tool name rejected" in event.lower() for event in events)\n'''
    tests.write_text(t, encoding='utf-8')
